package org.sigf.ui;
import org.sigf.app.*; import org.sigf.config.*; import org.sigf.security.*; import org.sigf.services.*; import org.sigf.ui.*; import org.sigf.domain.*;

import javafx.concurrent.Task; import javafx.geometry.Insets; import javafx.scene.control.*; import javafx.scene.layout.*; import javafx.stage.FileChooser; import java.io.*; import java.nio.charset.StandardCharsets; import java.nio.file.*; import java.util.*; import java.time.LocalDate; import java.util.concurrent.Callable;

/** A database-backed work area for the administrative and commercial modules. */
public final class OperationalPane extends VBox {
 private final Database db; private final Runnable onProfileChanged; private final Operations ops; private final SaleRecovery recovery; private final PurchaseRecovery purchaseRecovery; private final java.util.function.BiConsumer<String,UUID> onResolved; private PurchaseRecovery.Pending pendingPurchase; private final List<PurchaseItem> purchaseItems=new ArrayList<>(); private final Security.User user; private final String mode; private final TableView<List<String>> table=new TableView<>(); private CartView cartView; private final Label status=new Label(); private final List<CartItem> cart=new ArrayList<>(); private String query; private ReportGrid currentGrid; private final TextField filter=new TextField(); private final DatePicker from=new DatePicker(LocalDate.now().minusDays(30)),to=new DatePicker(LocalDate.now().plusDays(30)); private UUID pendingKey; private Long pendingClient; private String pendingMethod; private java.math.BigDecimal pendingTotal; private List<CartItem> pendingItems;
 public OperationalPane(Database db,Security.User user,String mode,String title,Runnable onProfileChanged,java.util.function.BiConsumer<String,UUID> onResolved){this.db=db;this.onProfileChanged=onProfileChanged;this.onResolved=onResolved;this.ops=new Operations(db);this.recovery=new SaleRecovery(db);this.purchaseRecovery=new PurchaseRecovery(db);this.user=user;this.mode=mode;this.query=mode;getStyleClass().add("workspace");setSpacing(14);Label heading=new Label(title);heading.getStyleClass().add("heading");getChildren().add(heading);table.setPlaceholder(new Label("Sin registros."));table.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_ALL_COLUMNS);VBox.setVgrow(table,Priority.ALWAYS);
  FlowPane actions=new FlowPane();actions.setHgap(8);actions.setVgap(8);Button refresh=button("Actualizar",this::refresh);actions.getChildren().add(refresh);
  switch(mode){
   case "suppliers","customers" -> {if(admin()){actions.getChildren().addAll(button("Nuevo",()->contact(false)),button("Editar",()->contact(true)));}}
   case "users" -> {if(admin())actions.getChildren().addAll(button("Nuevo usuario",()->account(false)),button("Editar usuario",()->account(true)));}
   case "batches" -> {if(admin())actions.getChildren().addAll(button("Ajustar",this::adjust),button("Bloquear / habilitar",this::block));}
   case "sales" -> {actions.getChildren().addAll(button("Ver comprobante",this::receipt),button("Imprimir comprobante",this::printReceipt));if(admin())actions.getChildren().add(button("Anular venta",this::voidSale));}
   case "pending" -> {actions.getChildren().addAll(button("Resolver venta",this::resolvePending),button("Cancelar solicitud",this::cancelPending));}
   case "purchase_pending" -> {if(admin())actions.getChildren().addAll(button("Resolver compra",this::resolvePurchase),button("Cancelar solicitud",this::cancelPurchase));}
   case "purchases" -> {if(admin())actions.getChildren().addAll(button("Agregar línea",this::purchaseAdd),button("Ver líneas",this::purchaseView),button("Registrar compra",this::purchaseCommit),button("Vaciar líneas",this::clearPurchase));}
   case "settings" -> {if(admin())actions.getChildren().addAll(button("Datos de la farmacia",()->ProfileDialog.open(getScene().getWindow(),db,user,()->{onProfileChanged.run();refresh();})),button("Serie interna (prueba)",this::internalSeries),button("Crear respaldo",this::backup),button("Modificar parámetro",this::setting));}
   case "reports" -> {ComboBox<String> choices=new ComboBox<>();choices.getItems().addAll("Existencias","Productos más vendidos","Ventas","Compras","Vencimientos","Movimientos","Resumen de IVA","Comprobantes internos","Anulaciones internas");if(admin())choices.getItems().add("Actividad administrativa");choices.setValue("Existencias");query="stock";choices.setOnAction(e->{query=switch(choices.getValue()){case "Productos más vendidos"->"top";case "Resumen de IVA"->"tax_summary";case "Comprobantes internos"->"internal_docs";case "Anulaciones internas"->"voided_docs";case "Ventas"->"sales";case "Compras"->"purchases";case "Vencimientos"->"batches";case "Movimientos"->"movements";case "Actividad administrativa"->"audit";default->"stock";};refresh();});actions.getChildren().addAll(choices,new Label("Desde"),from,new Label("Hasta"),to,button("Exportar CSV",this::export));}
   case "cart" -> {query="stock";actions.getChildren().addAll(button("Agregar producto",this::cartAdd),button("Cambiar cantidad",()->cartView.edit()),button("Quitar línea",()->cartView.remove()),button("Confirmar venta",this::checkout),button("Vaciar carrito",this::clearCart));}
  }
  filter.setPromptText("Filtrar filas visibles");filter.setPrefWidth(190);filter.textProperty().addListener((o,a,b)->filterRows());actions.getChildren().add(filter);
  if(mode.equals("cart")){setOnKeyPressed(e->{if(e.isControlDown()&&e.getCode()==javafx.scene.input.KeyCode.ENTER){checkout();e.consume();}else if(e.getCode()==javafx.scene.input.KeyCode.F2){cartAdd();e.consume();}});Label shortcuts=new Label("F2 agregar · Ctrl+Enter confirmar");shortcuts.getStyleClass().add("muted");getChildren().add(shortcuts);}getChildren().addAll(actions,table);if(mode.equals("cart")){cartView=new CartView(cart,()->currentGrid,()->pendingKey!=null);getChildren().add(cartView);}getChildren().add(status);refresh();
 }
 private boolean admin(){return user.role().equals("ADMIN");}
 private Button button(String label,Runnable action){Button b=new Button(label);b.setOnAction(e->action.run());return b;}
 private <T>void run(Callable<T> job,java.util.function.Consumer<T> success){setDisable(true);status.setText("Procesando…");Task<T> task=new Task<>(){protected T call()throws Exception{return job.call();}};task.setOnSucceeded(e->{setDisable(false);status.setText("Actualizado");success.accept(task.getValue());});task.setOnFailed(e->{setDisable(false);Throwable ex=task.getException();status.setText(pendingKey==null?"No se completó la operación":"Resultado incierto: reintente la misma venta");error(ex);});Thread t=new Thread(task);t.setDaemon(true);t.start();}
 private void refresh(){String q=query;LocalDate start=from.getValue(),end=to.getValue();run(()->mode.equals("pending")?pendingGrid():mode.equals("purchase_pending")?purchasePendingGrid():mode.equals("reports")?ops.report(q,start,end):ops.grid(q),this::display);}
 private ReportGrid pendingGrid()throws Exception {List<List<String>> rows=new ArrayList<>();for(var p:recovery.list(user))rows.add(List.of(p.id().toString(),p.customer()==null?"":p.customer().toString(),p.method(),p.total().toPlainString(),Integer.toString(p.items().size())));return new ReportGrid(List.of("Solicitud","Cliente","Pago","Total","Líneas"),rows);}
 private void resolvePending(){try{UUID id=UUID.fromString(selected().get(0));run(()->recovery.resolve(user,id),r->{info("Venta #"+r.id()+" registrada. Total: "+r.total());run(()->{recovery.acknowledge(user,id,false);return null;},x->{onResolved.accept("sale",id);refresh();});});}catch(Exception ex){error(ex);}}
 private void cancelPending(){try{UUID id=UUID.fromString(selected().get(0));Alert a=new Alert(Alert.AlertType.CONFIRMATION,"¿Cancelar esta solicitud pendiente? Una venta ya registrada no se cancelará.",ButtonType.OK,ButtonType.CANCEL);if(a.showAndWait().orElse(ButtonType.CANCEL)==ButtonType.OK)run(()->{recovery.acknowledge(user,id,true);return null;},x->{onResolved.accept("sale",id);refresh();});}catch(Exception ex){error(ex);}}
 private ReportGrid purchasePendingGrid()throws Exception{List<List<String>> rows=new ArrayList<>();for(var p:purchaseRecovery.list(user))rows.add(List.of(p.id().toString(),p.supplier()==null?"Sin proveedor":p.supplier().toString(),Integer.toString(p.items().size())));return new ReportGrid(List.of("Solicitud","Proveedor","Líneas"),rows);}
 private void resolvePurchase(){try{UUID id=UUID.fromString(selected().get(0));run(()->purchaseRecovery.resolve(user,id),number->{info("Compra #"+number+" registrada.");run(()->{purchaseRecovery.acknowledge(user,id,false);return null;},v->{onResolved.accept("purchase",id);refresh();});});}catch(Exception e){error(e);}}
 private void cancelPurchase(){try{UUID id=UUID.fromString(selected().get(0));Alert a=new Alert(Alert.AlertType.CONFIRMATION,"¿Cancelar esta solicitud? Una compra ya registrada no se cancelará.",ButtonType.OK,ButtonType.CANCEL);if(a.showAndWait().orElse(ButtonType.CANCEL)==ButtonType.OK)run(()->{purchaseRecovery.acknowledge(user,id,true);return null;},v->{onResolved.accept("purchase",id);refresh();});}catch(Exception e){error(e);}}
 public void resolvedElsewhere(String type,UUID id){if(type.equals("sale")&&id.equals(pendingKey)){pendingKey=null;pendingItems=null;cart.clear();refreshCart();status.setText("La venta pendiente fue resuelta; carrito vaciado.");}if(type.equals("purchase")&&pendingPurchase!=null&&id.equals(pendingPurchase.id())){pendingPurchase=null;purchaseItems.clear();status.setText("La compra pendiente fue resuelta; borrador vaciado.");}}
 private void purchaseAdd(){if(pendingPurchase!=null){error(new IllegalStateException("Resuelva primero la compra pendiente"));return;}run(()->ops.grid("stock"),grid->chooseRow("Seleccionar producto",grid.rows().stream().filter(row->row.size()>8&&Boolean.parseBoolean(row.get(8))).toList(),2,false,selected->{long product=Long.parseLong(selected.get(0));form("Lote · "+selected.get(2),new String[]{"Lote","Vence AAAA-MM-DD","Cantidad","Costo unitario"},new String[]{"","","1","0.00"},Set.of()).ifPresent(v->{try{var item=new PurchaseItem(product,v.get(0).trim(),LocalDate.parse(v.get(1)),Integer.parseInt(v.get(2)),new java.math.BigDecimal(v.get(3)));if(item.lot().isBlank()||!item.expiry().isAfter(LocalDate.now())||item.quantity()<=0||item.cost().signum()<0)throw new IllegalArgumentException("Revise lote, vencimiento, cantidad y costo");item.cost().setScale(2,java.math.RoundingMode.UNNECESSARY);purchaseItems.add(item);status.setText("Líneas de compra: "+purchaseItems.size());}catch(Exception e){error(e);}});}));}
 private void purchaseView(){if(purchaseItems.isEmpty()){info("No hay líneas.");return;}StringBuilder b=new StringBuilder();for(var i:purchaseItems)b.append("Producto ").append(i.productId()).append(" · ").append(i.lot()).append(" · ").append(i.quantity()).append(" x ").append(i.cost()).append('\n');info(b.toString());}
 private void purchaseCommit(){if(pendingPurchase!=null){submitPurchase();return;}if(purchaseItems.isEmpty()){error(new IllegalArgumentException("La compra está vacía"));return;}run(()->ops.grid("suppliers"),grid->chooseRow("Seleccionar proveedor",grid.rows().stream().filter(row->Boolean.parseBoolean(row.get(3))).toList(),1,false,row->{pendingPurchase=new PurchaseRecovery.Pending(UUID.randomUUID(),Long.valueOf(row.get(0)),List.copyOf(purchaseItems));submitPurchase();}));}
 private void submitPurchase(){PurchaseRecovery.Pending request=pendingPurchase;run(()->{purchaseRecovery.save(user,request);return purchaseRecovery.resolve(user,request.id());},id->{info("Compra registrada #"+id);run(()->{purchaseRecovery.acknowledge(user,request.id(),false);return null;},v->{pendingPurchase=null;purchaseItems.clear();refresh();});});}
 private void display(ReportGrid g){currentGrid=g;table.getColumns().clear();for(int i=0;i<g.columns().size();i++){final int idx=i;TableColumn<List<String>,String> c=new TableColumn<>(label(g.columns().get(i)));c.setCellValueFactory(v->new javafx.beans.property.ReadOnlyStringWrapper(v.getValue().get(idx)));c.setMinWidth(100);c.setPrefWidth(155);table.getColumns().add(c);}filterRows();}
 private void filterRows(){if(currentGrid==null)return;String q=filter.getText().toLowerCase(Locale.ROOT).trim();table.getItems().setAll(currentGrid.rows().stream().filter(row->row.stream().anyMatch(value->value.toLowerCase(Locale.ROOT).contains(q))).toList());if(mode.equals("cart"))refreshCart();}
 private static String label(String key){return switch(key){case "id"->"ID";case "name"->"Nombre";case "code"->"Código";case "sale_price"->"Precio sin IVA";case "tax_rate"->"IVA";case "minimum_stock"->"Mínimo";case "total"->"Total";case "vendible"->"Vendible";case "active"->"Activo";case "blocked"->"Bloqueado";case "lot"->"Lote";case "expires_on"->"Vencimiento";case "quantity"->"Cantidad";case "created_at"->"Fecha";case "coalesce"->"Dato";case "status"->"Estado";case "tax"->"Impuesto";case "subtotal"->"Subtotal";case "role"->"Rol";case "username"->"Usuario";case "action"->"Acción";case "details"->"Detalle";case "kind"->"Tipo";case "key"->"Parámetro";case "value"->"Valor";default->key.replace('_',' ');};}
 private List<String> selected(){List<String> r=table.getSelectionModel().getSelectedItem();if(r==null)throw new IllegalArgumentException("Seleccione una fila");return r;}
 private Optional<List<String>> form(String title,String[] labels,String[] values,Set<Integer> secret){Dialog<List<String>> d=new Dialog<>();d.setTitle(title);d.getDialogPane().getButtonTypes().addAll(ButtonType.OK,ButtonType.CANCEL);GridPane g=new GridPane();g.setPadding(new Insets(15));g.setHgap(10);g.setVgap(10);List<TextField> fields=new ArrayList<>();for(int i=0;i<labels.length;i++){TextField f=secret.contains(i)?new PasswordField():new TextField();f.setText(values[i]);fields.add(f);g.addRow(i,new Label(labels[i]),f);}d.getDialogPane().setContent(g);d.setResultConverter(b->b==ButtonType.OK?fields.stream().map(TextField::getText).toList():null);return d.showAndWait();}
 private void contact(boolean edit){try{List<String> row=edit?selected():null;boolean supplier=mode.equals("suppliers");String[] labels=supplier?new String[]{"Nombre","Teléfono","Activo (true/false)"}:new String[]{"Nombre","Teléfono","RUC (opcional)"};String[] vals=supplier?new String[]{edit?row.get(1):"",edit?row.get(2):"",edit?row.get(3):"true"}:new String[]{edit?row.get(1):"",edit?row.get(2):"",edit?row.get(3):""};form("Datos",labels,vals,Set.of()).ifPresent(v->{try{Long id=edit?Long.valueOf(row.get(0)):null;boolean active=!supplier||bool(v.get(2));run(()->{if(supplier)ops.contact(user,"supplier",id,v.get(0),v.get(1),active);else ops.customer(user,id,v.get(0),v.get(1),v.get(2));return null;},x->refresh());}catch(Exception ex){error(ex);}});}catch(Exception ex){error(ex);}}
 private static boolean bool(String s){if(!s.equalsIgnoreCase("true")&&!s.equalsIgnoreCase("false"))throw new IllegalArgumentException("Use true o false");return Boolean.parseBoolean(s);}
 private void account(boolean edit){try{List<String> row=edit?selected():null;form("Usuario",new String[]{"Usuario","Contraseña (vacía conserva)","Rol ADMIN o CASHIER","Activo true/false"},new String[]{edit?row.get(1):"","",edit?row.get(2):"CASHIER",edit?row.get(3):"true"},Set.of(1)).ifPresent(v->{try{Long id=edit?Long.valueOf(row.get(0)):null;boolean active=bool(v.get(3));run(()->{ops.user(user,id,v.get(0),v.get(1),v.get(2).toUpperCase(Locale.ROOT),active);return null;},x->refresh());}catch(Exception ex){error(ex);}});}catch(Exception ex){error(ex);}}
 private void adjust(){try{long id=Long.parseLong(selected().get(0));form("Ajustar lote",new String[]{"Variación (+/-)","Motivo"},new String[]{"",""},Set.of()).ifPresent(v->{try{int n=Integer.parseInt(v.get(0));run(()->{ops.adjust(user,id,n,v.get(1));return null;},x->refresh());}catch(Exception ex){error(ex);}});}catch(Exception ex){error(ex);}}
 private void block(){try{var row=selected();long id=Long.parseLong(row.get(0));boolean b=!bool(row.get(6));run(()->{ops.block(user,id,b);return null;},x->refresh());}catch(Exception ex){error(ex);}}
 private void receipt(){try{long id=Long.parseLong(selected().get(0));run(()->ops.receipt(id),OperationalPane::info);}catch(Exception ex){error(ex);}}
 private void printReceipt(){try{long id=Long.parseLong(selected().get(0));run(()->ops.receipt(id),text->{javafx.print.PrinterJob job=javafx.print.PrinterJob.createPrinterJob();if(job==null){error(new IllegalStateException("No hay impresora disponible"));return;}if(job.showPrintDialog(getScene().getWindow())){var layout=job.getJobSettings().getPageLayout();int width=Math.max(20,(int)(layout.getPrintableWidth()/6));int height=Math.max(5,(int)(layout.getPrintableHeight()/14)-2);List<String> lines=new ArrayList<>();for(String raw:text.split("\n",-1)){if(raw.isEmpty())lines.add("");else for(int i=0;i<raw.length();i+=width)lines.add(raw.substring(i,Math.min(i+width,raw.length())));}boolean ok=true;for(int i=0;i<lines.size()&&ok;i+=height){javafx.scene.text.Text page=new javafx.scene.text.Text(String.join("\n",lines.subList(i,Math.min(i+height,lines.size()))));page.setFont(javafx.scene.text.Font.font("Monospaced",9));ok=job.printPage(page);}if(ok)job.endJob();else{job.cancelJob();error(new IllegalStateException("No se pudo imprimir el comprobante"));}}});}catch(Exception ex){error(ex);}}
 private void voidSale(){try{long id=Long.parseLong(selected().get(0));form("Anular venta "+id,new String[]{"Motivo"},new String[]{""},Set.of()).ifPresent(v->run(()->{ops.voidSale(user,id,v.get(0));return null;},x->refresh()));}catch(Exception ex){error(ex);}}
 private void backup(){FileChooser executable=new FileChooser();executable.setTitle("Seleccione pg_dump de PostgreSQL");executable.getExtensionFilters().add(new FileChooser.ExtensionFilter("pg_dump", "pg_dump", "pg_dump.exe"));File pg=executable.showOpenDialog(getScene().getWindow());if(pg==null)return;FileChooser dest=new FileChooser();dest.setTitle("Guardar respaldo PostgreSQL");dest.setInitialFileName("sigf-respaldo-"+LocalDate.now()+".dump");dest.getExtensionFilters().add(new FileChooser.ExtensionFilter("Respaldo PostgreSQL","*.dump"));File file=dest.showSaveDialog(getScene().getWindow());if(file==null)return;run(()->{new BackupService(db).create(user,pg.toPath(),file.toPath());return null;},x->info("Respaldo creado. Guárdelo en un lugar protegido y compruebe su restauración."));}
 private void internalSeries(){form("Serie interna de prueba (sin valor fiscal)",new String[]{"Serie","Próximo número"},new String[]{"DEMO","1"},Set.of()).ifPresent(v->{try{long next=Long.parseLong(v.get(1));run(()->{ops.internalSeries(user,v.get(0),next);return null;},x->info("Serie interna actualizada. No constituye autorización fiscal."));}catch(Exception e){error(e);}});}
 private void setting(){try{var row=selected();form("Modificar configuración",new String[]{"Valor"},new String[]{row.get(1)},Set.of()).ifPresent(v->run(()->{ops.setting(user,row.get(0),v.get(0));return null;},x->refresh()));}catch(Exception ex){error(ex);}}
 private void clearPurchase(){if(pendingPurchase==null){purchaseItems.clear();status.setText("Compra vacía");return;}UUID id=pendingPurchase.id();run(()->{purchaseRecovery.cancelOrDiscard(user,id);return null;},v->{pendingPurchase=null;purchaseItems.clear();onResolved.accept("purchase",id);status.setText("Borrador de compra cancelado");});}
 private void clearCart(){if(pendingKey==null){cart.clear();refreshCart();status.setText("Carrito vacío");return;}UUID id=pendingKey;run(()->{recovery.cancelOrDiscard(user,id);return null;},v->{pendingKey=null;pendingItems=null;cart.clear();refreshCart();onResolved.accept("sale",id);status.setText("Carrito y solicitud cancelados");});}
 private void refreshCart(){if(cartView!=null)cartView.refresh();}
 private void cartAdd(){try{cartView.add(selected());}catch(Exception e){error(e);}}
 private void checkout(){if(pendingKey!=null){submitPending();return;}if(cart.isEmpty()){error(new IllegalArgumentException("Carrito vacío"));return;}List<CartItem> snapshot=List.copyOf(cart);run(()->ops.quoteDetailed(snapshot),detail->{Receipt quote=detail.totals();Alert confirm=new Alert(Alert.AlertType.CONFIRMATION,"Subtotal: "+quote.subtotal()+"\nImpuesto: "+quote.tax()+"\nTotal: "+quote.total()+"\n\nComprobante interno sin valor fiscal. ¿Continuar?",ButtonType.OK,ButtonType.CANCEL);if(confirm.showAndWait().orElse(ButtonType.CANCEL)!=ButtonType.OK)return;run(()->ops.grid("customers"),grid->chooseRow("Seleccionar cliente",grid.rows(),1,true,row->{Long client=row==null?null:Long.valueOf(row.get(0));ChoiceDialog<String> payment=new ChoiceDialog<>("Efectivo",List.of("Efectivo","Tarjeta","Transferencia"));payment.setTitle("Forma de pago");payment.setHeaderText("Seleccione la forma de pago");payment.showAndWait().ifPresent(choice->{pendingClient=client;pendingMethod=switch(choice){case "Tarjeta"->"CARD";case "Transferencia"->"TRANSFER";default->"CASH";};pendingKey=UUID.randomUUID();pendingItems=snapshot;pendingTotal=quote.total();SaleRecovery.Pending request=new SaleRecovery.Pending(pendingKey,pendingClient,pendingMethod,pendingTotal,pendingItems,detail.lines());run(()->{recovery.save(user,request);return null;},x->submitPending());});}));});}
 private void chooseRow(String title,List<List<String>> rows,int nameColumn,boolean optional,java.util.function.Consumer<List<String>> chosen){LinkedHashMap<String,List<String>> options=new LinkedHashMap<>();if(optional)options.put("Consumidor final",null);for(List<String> row:rows)options.put(row.get(0)+" · "+row.get(nameColumn),row);if(options.isEmpty()){error(new IllegalArgumentException("No hay registros disponibles"));return;}ChoiceDialog<String> dialog=new ChoiceDialog<>(options.keySet().iterator().next(),options.keySet());dialog.setTitle(title);dialog.setHeaderText(title);dialog.showAndWait().ifPresent(value->chosen.accept(options.get(value)));}
 private void submitPending(){UUID id=pendingKey;run(()->recovery.resolve(user,id),receipt->{info("Comprobante de venta #"+receipt.id()+"\nSubtotal: "+receipt.subtotal()+"\nImpuesto: "+receipt.tax()+"\nTotal: "+receipt.total());run(()->{recovery.acknowledge(user,id,false);return null;},x->{pendingKey=null;pendingItems=null;cart.clear();refreshCart();refresh();});});}
 private void export(){FileChooser chooser=new FileChooser();chooser.setTitle("Guardar reporte CSV");chooser.getExtensionFilters().add(new FileChooser.ExtensionFilter("CSV", "*.csv"));File f=chooser.showSaveDialog(getScene().getWindow());if(f==null)return;List<String> lines=new ArrayList<>();lines.add(csv(table.getColumns().stream().map(TableColumn::getText).toList()));for(var row:table.getItems())lines.add(csv(row));try{Files.write(f.toPath(),lines,StandardCharsets.UTF_8);info("Reporte exportado.");}catch(IOException e){error(e);}}
 private static String csv(List<String> values){return values.stream().map(v->"\""+((!v.isEmpty() && "=+-@".indexOf(v.charAt(0))>=0)?"'"+v:v).replace("\"","\"\"")+"\"").collect(java.util.stream.Collectors.joining(","));}
 private static void info(String s){new Alert(Alert.AlertType.INFORMATION,s,ButtonType.OK).showAndWait();}private static void error(Throwable e){new Alert(Alert.AlertType.ERROR,Objects.toString(e.getMessage(),"Error inesperado"),ButtonType.OK).showAndWait();}
}
